-- Add abs (Mage) and mobility (Rörlighet) exercises to the Strength Hub catalog.
-- Generated by scripts/core-catalog-migration.mjs from src/strength-catalog-core.js; edit those, not the .sql.
-- Only new exercise ids are added. Saved workouts, XP, ranks and baselines are unchanged.
begin;
alter function public.arc_strength_meta(text) rename to arc_strength_meta_v13;
create function public.arc_strength_meta(id text) returns jsonb
language sql immutable set search_path=public,pg_temp as $$
 select coalesce((select value from jsonb_array_elements('[{"id":"situp","name":"Situps","muscle":"Mage","equipment":"Kroppsvikt","family":"core","pose":"situp","thresholds":[5,15,25,40,60,80],"cue":"Ligg på rygg med böjda knän och fötterna i golvet. Rulla upp med bålen tills du sitter och sänk kontrollerat. Dra inte i nacken.","unit":"reps"},{"id":"crunch","name":"Crunches","muscle":"Mage","equipment":"Kroppsvikt","family":"core","pose":"crunch","thresholds":[10,20,35,50,75,100],"cue":"Ligg på rygg med böjda knän. Lyft skulderbladen från golvet genom att spänna magen, och sänk lugnt. Ländryggen stannar i golvet.","unit":"reps"},{"id":"reverse-crunch","name":"Omvända crunches","muscle":"Mage","equipment":"Kroppsvikt","family":"core","pose":"reverse-crunch","thresholds":[5,10,15,25,35,50],"cue":"Ligg på rygg med böjda knän i luften. Rulla upp bäckenet mot bröstet med magen, utan att gunga, och sänk långsamt.","unit":"reps"},{"id":"bicycle-crunch","name":"Cykelcrunch","muscle":"Mage","equipment":"Kroppsvikt","family":"core","pose":"crunch","thresholds":[10,20,30,45,60,80],"cue":"För motsatt armbåge mot knät medan andra benet sträcks. Byt sida lugnt. Logga totala repetitioner.","unit":"reps"},{"id":"v-up","name":"V-ups","muscle":"Mage","equipment":"Kroppsvikt","family":"core","pose":"v-up","thresholds":[3,8,12,18,25,35],"cue":"Ligg utsträckt och lyft raka ben och överkropp samtidigt så att händerna når mot tårna. Sänk kontrollerat utan att släppa spänningen.","unit":"reps"},{"id":"russian-twist","name":"Russian twist","muscle":"Mage","equipment":"Kroppsvikt","family":"core","pose":"twist","thresholds":[10,20,30,40,60,80],"cue":"Sitt lutad bakåt med rak rygg och vrid överkroppen från sida till sida. Fötterna kan vara i golvet. Logga totala repetitioner.","unit":"reps"},{"id":"leg-raise","name":"Benlyft liggande","muscle":"Mage","equipment":"Kroppsvikt","family":"core","pose":"leg-raise","thresholds":[5,10,15,20,30,40],"cue":"Ligg på rygg med händerna längs sidorna. Lyft raka ben till lodrätt och sänk långsamt utan att ländryggen släpper golvet.","unit":"reps"},{"id":"captains-chair","name":"Benlyft i captain''s chair","muscle":"Mage","equipment":"Maskin","family":"core","pose":"captains-chair","thresholds":[5,10,15,20,25,30],"cue":"Stöd underarmarna på dynorna med ryggen mot ryggstödet. Lyft knäna eller raka ben mot bröstet utan att svinga, och sänk kontrollerat.","unit":"reps"},{"id":"hanging-knee-raise","name":"Hängande knälyft","muscle":"Mage","equipment":"Räcke","family":"core","pose":"hanging-knee","thresholds":[3,8,12,18,25,30],"cue":"Häng med aktiva skuldror. Dra knäna mot bröstet med magen och sänk lugnt utan att gunga.","unit":"reps"},{"id":"hanging-leg-raise","name":"Hängande benlyft","muscle":"Mage","equipment":"Räcke","family":"core","pose":"hanging-raise","thresholds":[1,3,6,10,15,20],"cue":"Häng med aktiva skuldror och lyft raka ben till minst vågrätt. Sänk kontrollerat och undvik sving.","unit":"reps"},{"id":"ab-wheel","name":"Ab wheel-utrullning","muscle":"Mage","equipment":"Kroppsvikt","family":"core","pose":"ab-wheel","thresholds":[1,3,6,10,15,20],"cue":"Börja på knä med hjulet under axlarna. Rulla fram så långt du kan behålla en rak rygg och rulla tillbaka med magen.","unit":"reps"},{"id":"cable-crunch","name":"Kabelcrunch","muscle":"Mage","equipment":"Kabel","family":"core","pose":"cable-crunch","thresholds":[0.2,0.35,0.5,0.65,0.8,1],"cue":"Knästå framför kabeln med repet vid huvudet. Rulla ner med magen mot låren utan att dra med armarna. Jämför på samma maskin.","unit":"kg"},{"id":"hip-flexor-stretch","name":"Höftböjarstretch","muscle":"Rörlighet","equipment":"Matta","family":"mobility","pose":"kneel-lunge","thresholds":[20,30,45,60,90,120],"cue":"Knästå i utfall, spänn sätet och för höften lätt framåt tills det känns på framsidan av bakre höften. Logga tid per sida.","unit":"sek"},{"id":"couch-stretch","name":"Couch stretch","muscle":"Rörlighet","equipment":"Matta","family":"mobility","pose":"kneel-lunge","thresholds":[20,30,45,60,90,120],"cue":"Bakre knät mot golvet och foten mot en vägg eller soffa. Res överkroppen och spänn sätet. Gå bara så långt det känns bekvämt. Logga tid per sida.","unit":"sek"},{"id":"pigeon","name":"Duvan","muscle":"Rörlighet","equipment":"Matta","family":"mobility","pose":"pigeon","thresholds":[20,30,45,60,90,120],"cue":"Främre benet vikt framför dig och bakre benet rakt bakåt. Håll höften jämn och andas lugnt. Logga tid per sida.","unit":"sek"},{"id":"worlds-greatest","name":"World''s greatest stretch","muscle":"Rörlighet","equipment":"Matta","family":"mobility","pose":"reach-lunge","thresholds":[3,5,8,10,12,15],"cue":"Ta ett långt utfall, sätt handen i golvet och vrid upp andra armen mot taket. Byt sida. Logga repetitioner per sida.","unit":"reps"},{"id":"ninety-ninety","name":"90/90-höftrotation","muscle":"Rörlighet","equipment":"Matta","family":"mobility","pose":"ninety","thresholds":[4,8,12,16,20,24],"cue":"Sitt med båda knäna böjda i 90 grader åt samma håll. Rotera knäna till andra sidan med rak överkropp. Logga totala repetitioner.","unit":"reps"},{"id":"deep-squat-hold","name":"Djup knäböj, stillastående","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"mobility","pose":"deep-squat","thresholds":[15,30,45,60,90,120],"cue":"Sjunk ner i en djup knäböj med hälarna i golvet och bröstet upp. Håll i något framför dig om det behövs.","unit":"sek"},{"id":"childs-pose","name":"Barnets position","muscle":"Rörlighet","equipment":"Matta","family":"mobility","pose":"child","thresholds":[20,30,45,60,90,120],"cue":"Sitt på hälarna, fäll fram och sträck armarna framåt. Låt ryggen och axlarna slappna av och andas lugnt.","unit":"sek"},{"id":"cobra","name":"Kobran","muscle":"Rörlighet","equipment":"Matta","family":"mobility","pose":"cobra","thresholds":[15,30,45,60,90,120],"cue":"Ligg på mage och res överkroppen på händerna med höften kvar i golvet. Håll axlarna låga och gå bara till en bekväm höjd.","unit":"sek"},{"id":"open-book","name":"Öppen bok, bröstrygg","muscle":"Rörlighet","equipment":"Matta","family":"mobility","pose":"open-book","thresholds":[4,6,8,10,12,15],"cue":"Ligg på sidan med böjda knän och armarna framåt. Öppna översta armen bakåt och följ med blicken. Logga repetitioner per sida.","unit":"reps"},{"id":"hamstring-stretch","name":"Baksida lår-stretch","muscle":"Rörlighet","equipment":"Matta","family":"mobility","pose":"seated-fold","thresholds":[20,30,45,60,90,120],"cue":"Sitt med raka ben och fäll framåt från höften med lång rygg. Sträck bara så långt det känns bekvämt.","unit":"sek"},{"id":"butterfly","name":"Fjärilsstretch","muscle":"Rörlighet","equipment":"Matta","family":"mobility","pose":"butterfly","thresholds":[20,30,45,60,90,120],"cue":"Sitt med fotsulorna mot varandra och låt knäna sjunka utåt. Fäll lätt framåt med rak rygg.","unit":"sek"},{"id":"band-dislocate","name":"Axelgenomförning med band","muscle":"Rörlighet","equipment":"Gummiband","family":"mobility","pose":"dislocate","thresholds":[5,8,10,12,15,20],"cue":"Håll ett gummiband brett med raka armar och för det över huvudet och bakåt i en jämn båge. Bredda greppet om axlarna tar emot.","unit":"reps"},{"id":"knee-to-wall","name":"Fotledsrörlighet mot vägg","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"mobility","pose":"kneel-lunge","thresholds":[5,8,10,12,15,20],"cue":"Stå med foten en bit från väggen och för knät mot väggen med hälen kvar i golvet. Logga repetitioner per sida.","unit":"reps"}]'::jsonb) where value->>'id'=id), public.arc_strength_meta_v13(id))
$$;
revoke all on function public.arc_strength_meta_v13(text) from public,anon,authenticated;
create or replace function public.training_expansion_ready() returns integer language sql stable as $$select 14$$;
notify pgrst,'reload schema';
commit;
